    'IBAN has the wrong format or length': ['Napačna oblika ali dolžina IBAN', 'Pogrešan oblik ili duljina IBAN-a'],
    'IBAN check digits are wrong': ['Napačni kontrolni števki IBAN', 'Pogrešne kontrolne znamenke IBAN-a'],
    'Account number without the IBAN prefix': ['Številka računa brez predpone IBAN', 'Broj računa bez IBAN prefiksa'],
    'IBAN with spaces or lower case': ['IBAN s presledki ali malimi črkami', 'IBAN s razmacima ili malim slovima'],
