    'Barcode lost its leading zero': ['Črtni kodi manjka vodilna ničla', 'Barkodu nedostaje početna nula'],
    'Barcode with spaces or dashes': ['Črtna koda s presledki ali vezaji', 'Barkod s razmacima ili crticama'],
